import { types } from "node:util";
import type { World } from "../../../../core/domain/world";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { animalOriginalRolePlayer, type AnimalOriginalPlayer } from "./roster";
import {
  freshFoxCubState,
  freshPufferfishState,
  freshWhiteCatState,
  readFoxCubState,
  readPufferfishState,
  readWhiteCatState,
  payFoxCubChoice,
  payPufferfishChoice,
  notePufferfishKnifeDeath,
  deferWhiteCat,
  expireWhiteCat,
  type FoxCubState,
  type PufferfishState,
  type WhiteCatState,
} from "./state";

/** 同一原槽、当前 live 对象与已提交 JSON 的捕获记录；具体 T 保留三族原形状，不复制 live 数据。 */
export interface Resource<T extends object> {
  readonly actor: AnimalOriginalPlayer;
  readonly key: string;
  state: T;
  json: string;
  readonly read: (value: unknown) => T;
}
/** 只接受原可枚举 data descriptor；Proxy、访问器和缺失键维持原拒绝，不执行输入 getter。 */
export function descriptor(value: unknown, key: string): PropertyDescriptor | undefined {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d && d.enumerable ? d : undefined;
}
/** 原 Node 安全数据副本与 65536 限制；序列化失败返回 null，不替换或冻结输入。 */
export function plainJson(value: unknown): string | null {
  try {
    return JSON.stringify(snapshotPlainData(value, new Set(), 0, 65536));
  } catch {
    return null;
  }
}
/** 捕获已由 profile 初始化的原槽；descriptor → JSON → schema → fresh 比较的顺序保持。 */
export function captureResource<T extends object>(
  world: World,
  role: "fox_cub" | "pufferfish" | "white_cat",
  key: string,
  read: (value: unknown) => T,
  fresh: T,
): Resource<T> {
  const actor = animalOriginalRolePlayer(world, role),
    d = actor && descriptor(actor.privateState, key),
    value = d?.value,
    json = plainJson(value);
  if (
    !actor ||
    !d?.writable ||
    json === null ||
    JSON.stringify(read(value)) !== JSON.stringify(fresh)
  )
    throw Error("animal_initial_resource_invalid");
  return { actor, key, state: value as T, json, read };
}
/** 原可写 descriptor、同状态引用和已提交 JSON 三项不变量；不以合法副本恢复已停 owner。 */
export function resourceCurrent<T extends object>(r: Resource<T>): boolean {
  const d = descriptor(r.actor.privateState, r.key);
  return !!d?.writable && d.value === r.state && plainJson(r.state) === r.json;
}
function replaceResource<T extends object>(r: Resource<T>, next: T, encoded: string): void {
  // 调用方已在最后外部回调之后核对可写数据槽；保持 privateState → state → json 的原写入前缀。
  r.actor.privateState[r.key] = next;
  r.state = next;
  r.json = encoded;
}

// 只冻结贡献声明与入口表；可写 live 状态及替换语义保持原机制所有权。
/** 子狐 pass 仍只追加历史；实际付款、效果与终止时点由原夜间租约判断。 */
export const FOX_STATE_SLOT = Object.freeze({
  create: freshFoxCubState,
  schema: readFoxCubState,
  allowedWrites: Object.freeze({ choose: payFoxCubChoice, commit: replaceResource }),
  checkpoint: Object.freeze({
    encode: (state: FoxCubState): string => JSON.stringify(state),
    decode: (readJson: () => string): FoxCubState => JSON.parse(readJson()) as FoxCubState,
  }),
  invalidations: Object.freeze({ current: resourceCurrent }),
});

/** 河豚主动报复与实际狼刀死亡独立计付；本 owner 不把它们归成同一个使用次数。 */
export const PUFFER_STATE_SLOT = Object.freeze({
  create: freshPufferfishState,
  schema: readPufferfishState,
  allowedWrites: Object.freeze({
    choose: payPufferfishChoice,
    knifeDeath: notePufferfishKnifeDeath,
    commit: replaceResource,
  }),
  checkpoint: Object.freeze({
    encode: (state: PufferfishState): string => JSON.stringify(state),
    decode: (readJson: () => string): PufferfishState => JSON.parse(readJson()) as PufferfishState,
  }),
  invalidations: Object.freeze({ current: resourceCurrent }),
});

/** 白猫只记录延迟及实际单元到期；Alive 与遗言仍由原死亡结算拥有。 */
export const CAT_STATE_SLOT = Object.freeze({
  create: freshWhiteCatState,
  schema: readWhiteCatState,
  allowedWrites: Object.freeze({ defer: deferWhiteCat, expire: expireWhiteCat, commit: replaceResource }),
  checkpoint: Object.freeze({
    encode: (state: WhiteCatState): string => JSON.stringify(state),
    decode: (readJson: () => string): WhiteCatState => JSON.parse(readJson()) as WhiteCatState,
  }),
  invalidations: Object.freeze({ current: resourceCurrent }),
});

/**
 * 负责收集河豚反噬选择，输入为 World、事件数组、Provider／网关、日期与原单元对象。
 * 当前单元／actor 及绑定请求决定资格；校验后先提交回执，再按原票型政策发表揭示与目标。
 * 输出为捕获的目标数组；成功建立 scope 并进入原 try 后才由 finally 关闭，库存及原票源归 authority，不提交死亡波。
 * 不变量：无待选 actor 不读取构造依赖；有效 actor 后在原点 new 原独立工厂，不复用 Voting 的普通投票工厂。
 */
import { ANIMAL_DREAM_POLICY } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import type { ActionProvider } from "../../../../core/domain/actions";
import type { GameEvent } from "../../../../core/domain/events";
import { Phase } from "../../../../core/domain/identity";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import {
  animalPufferChoiceActor,
  animalAuthoritySnapshot,
  animalPufferReaction,
} from "./authority";
import {
  openAnimalRequest,
  animalRequestScope,
  readAnimalTool,
  commitAnimalRequest,
  closeAnimalRequest,
} from "./requests";
import { appendAnimalFact } from "./facts";
export async function runAnimalPufferChoice(
  world: World,
  events: GameEvent[],
  provider: ActionProvider,
  gateway: ToolGateway,
  day: number,
  unit: object,
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
): Promise<readonly number[]> {
  const actorId = animalPufferChoiceActor(world, unit);
  if (actorId === null) return [];
  // 独立构造／create 先于 openAnimalRequest 和 try；这两步抛错时尚无此请求 scope，不能新增 finally 关闭。
  const request = new construction.requestFactory(world, events, day).create({
      actorId,
      phase: Phase.Voting,
      allowedTools: ["puffer_retaliate"],
      stage: "puffer_reaction",
      requiresAction: true,
      summary: { key: "action.puffer_retaliate.directive" },
      context: { allow_fallback: false, action_failure_policy: "error" },
    }),
    scope = openAnimalRequest(world, request, unit);
  try {
    const raw = await provider.getAction(request),
      call = readAnimalTool(raw);
    if (animalRequestScope(world, request) !== scope || call?.name !== "puffer_retaliate")
      throw Error("animal_required_action_invalid");
    const valid = gateway.validateAndSanitize(world, actorId, call, {
      phase: Phase.Voting,
      day,
      animalScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw Error("animal_required_action_invalid");
    const receipt = commitAnimalRequest(world, scope, valid.sanitizedCall);
    if (!("activate" in receipt)) throw Error("animal_receipt_invalid");
    appendAnimalFact(world, events, "animal_puffer_decided", {
      policy: ANIMAL_DREAM_POLICY,
      actorId,
      ...receipt,
    });
    const targetIds = [...animalPufferReaction(world, unit)];
    if (receipt.activate) {
      appendAnimalFact(world, events, "animal_puffer_revealed", {
        policy: ANIMAL_DREAM_POLICY,
        day,
        actorId,
        reason: "retaliation",
      });
      const snapshot = animalAuthoritySnapshot(world)!;
      appendAnimalFact(world, events, "animal_puffer_targets", {
        policy: ANIMAL_DREAM_POLICY,
        day,
        actorId,
        targetIds,
        round:
          snapshot.policies!.ballotPolicy === "awa_first_ballot_v1"
            ? 1
            : snapshot.unit!.finalRound!,
      });
    }
    return targetIds;
  } finally {
    closeAnimalRequest(scope);
  }
}

import { types } from "node:util";
import { z } from "zod";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import type { World } from "../../../../core/domain/world";

type Kind = "fox" | "puffer";
interface Header {
  readonly kind: Kind;
  readonly actorId: number;
  readonly day: number;
  readonly candidates: readonly number[] | null;
}
interface Alias {
  readonly request: object;
  readonly context: object;
  readonly deadline: number | undefined;
}
interface Envelope {
  readonly world: World;
  readonly original: Alias;
  readonly body: string;
  readonly header: Header;
  readonly aliases: Map<object, Alias>;
  deadline: number | null;
  withdrawn: boolean;
}
const envelopes = new WeakMap<object, Envelope>();
const now = Date.now.bind(Date);
const id = z.number().int().positive().safe(),
  names = z.enum(["fox_distract", "puffer_retaliate"]),
  requestSchema = z.strictObject({
    phase: z.enum(["night", "voting"]),
    actorId: id,
    allowedTools: z.array(names).length(1),
    context: z.looseObject({
